<script setup>
import { ref } from 'vue'
import { useScreen, toast } from '@/common/screen.js'
const s = useScreen(4), draft = ref(''), mute = ref(false), pinned = ref(false)
const questions = ['你最想体验的当地手作是？','有推荐的必去小店吗？','一起逛早市或市集？','需要拼车 / 拼住吗？','其他想聊的话题？']
const groupTools = [{label:'群公告',icon:'volume-2',click:()=>s.value=3},{label:'活动日历',icon:'calendar-days',click:()=>toast('活动日历')},{label:'文件',icon:'folder',click:()=>toast('群文件')},{label:'位置',icon:'map-pin',click:()=>toast('共享位置')},{label:'更多',icon:'ellipsis',click:()=>s.value=3}]
const members = [{name:'小院管家',avatar:'/static/media/chat-member-1.jpg',admin:true},{name:'阿布在大理',avatar:'/static/media/community-avatar-abu.jpg'},{name:'山野来信',avatar:'/static/media/community-avatar-shanye.jpg'},{name:'小鹿同学',avatar:'/static/media/chat-avatar-lu.jpg'},{name:'云朵不说话',avatar:'/static/media/chat-member-5.jpg'}]
const tripActivities = ['手作体验','逛市集','城市漫步','户外徒步','咖啡探店','摄影创作','美食探索','其他']
const selectedActivities = ref(['手作体验'])
const toggleActivity = (a) => { const i=selectedActivities.value.indexOf(a); if(i>=0) selectedActivities.value.splice(i,1); else selectedActivities.value.push(a) }
</script>

